"""ARB Memory bus helpers require a Redis client with decode_responses=True."""

import json
import logging
import math
import os
import threading
import uuid

import redis


logger = logging.getLogger(__name__)
PREFIX = os.environ.get("ARB_MEMORY_PREFIX", "")
MAXLEN = 10_000
REPLY_TTL = 30
GROUP = "arbmem-memory"


def reads_stream(prefix=PREFIX):
    return f"{prefix}arbmem:reads"


def writes_stream(prefix=PREFIX):
    return f"{prefix}arbmem:writes"


def reply_key(cid, prefix=PREFIX):
    return f"{prefix}arbmem:reply:{cid}"


def ensure_group(redis, stream, group):
    try:
        redis.xgroup_create(stream, group, id="$", mkstream=True)
    except Exception as exc:
        if "BUSYGROUP" not in str(exc):
            raise


def new_ulid():
    return uuid.uuid4().hex


def memory_write(
    redis,
    *,
    artefact=None,
    hints=(),
    source="seat",
    author="unknown",
    ulid=None,
    prefix=PREFIX,
):
    ulid = ulid or new_ulid()
    payload_hints = []
    for hint in hints:
        payload_hint = dict(hint)
        payload_hint.setdefault("source", source)
        payload_hint.setdefault("author", author)
        payload_hints.append(payload_hint)

    if artefact is not None and payload_hints:
        kind = "artefact+hints"
    elif artefact is not None:
        kind = "artefact"
    else:
        kind = "hints"

    payload = {
        "ulid": ulid,
        "kind": kind,
        "artefact": artefact,
        "hints": payload_hints,
    }
    redis.xadd(
        writes_stream(prefix),
        {"ulid": ulid, "payload": json.dumps(payload)},
        maxlen=MAXLEN,
        approximate=True,
    )
    return ulid


def _prepare_hints(hints, embed):
    prepared = []
    for hint in hints:
        row = dict(hint)
        row["embedding"] = embed(row["text"])
        prepared.append(row)
    return prepared


def handle_write_intent(conn, intent, *, embed):
    from . import store

    hints = _prepare_hints(intent.get("hints", ()), embed)
    with conn.transaction():
        row = conn.execute(
            "INSERT INTO idempotency_keys (key) VALUES (%s) ON CONFLICT DO NOTHING RETURNING key",
            (intent["ulid"],),
        ).fetchone()
        if row is None:
            return "duplicate"
        store.write_artefact_and_hints(conn, artefact=intent.get("artefact"), hints=hints)
        return "written"


class WriteLoop:
    def __init__(self, redis, conn, *, embed, prefix=PREFIX, consumer="writer", block_ms=1000):
        self.redis = redis
        self.conn = conn
        self.embed = embed
        self.prefix = prefix
        self.consumer = consumer
        self.block_ms = block_ms
        self.stream = writes_stream(prefix)
        self.running = False
        ensure_group(self.redis, self.stream, GROUP)

    def read_one(self):
        rows = self.redis.xreadgroup(
            GROUP,
            self.consumer,
            {self.stream: ">"},
            count=1,
            block=self.block_ms,
        )
        entry = self._one_from_rows(rows)
        if entry is None:
            return None
        entry_id, fields = entry
        return entry_id, self._parse_intent(fields)

    def handle_and_ack(self, entry_id, intent):
        handle_write_intent(self.conn, intent, embed=self.embed)
        self.redis.xack(self.stream, GROUP, entry_id)

    def drain_pending(self):
        while True:
            try:
                rows = self.redis.xreadgroup(GROUP, self.consumer, {self.stream: "0"}, count=1)
                entry = self._one_from_rows(rows)
                if entry is None:
                    return
                if not self._handle_entry(*entry):
                    return
            except Exception:
                logger.exception("write loop pending drain failed")
                return

    def run(self):
        self.running = True
        self.drain_pending()
        while self.running:
            try:
                rows = self.redis.xreadgroup(
                    GROUP,
                    self.consumer,
                    {self.stream: ">"},
                    count=1,
                    block=self.block_ms,
                )
                entry = self._one_from_rows(rows)
                if entry is not None:
                    self._handle_entry(*entry)
            except Exception:
                logger.exception("write loop failed")

    def stop(self):
        self.running = False

    @staticmethod
    def _one_from_rows(rows):
        if not rows:
            return None
        _, entries = rows[0]
        if not entries:
            return None
        return entries[0]

    @staticmethod
    def _parse_intent(fields):
        intent = json.loads(fields["payload"])
        if not isinstance(intent, dict) or "ulid" not in intent:
            raise ValueError("write intent missing required ulid")
        return intent

    def _ack(self, entry_id):
        try:
            self.redis.xack(self.stream, GROUP, entry_id)
        except Exception:
            logger.exception("write loop failed to ack entry %s", entry_id)

    def _handle_entry(self, entry_id, fields):
        try:
            intent = self._parse_intent(fields)
        except (KeyError, TypeError, json.JSONDecodeError, ValueError):
            logger.exception("dropping malformed write entry %s", entry_id)
            self._ack(entry_id)
            return True

        try:
            handle_write_intent(self.conn, intent, embed=self.embed)
        except Exception as exc:
            if not _is_retryable_write_error(exc):
                logger.exception("dropping invalid write entry %s", entry_id)
                self._ack(entry_id)
                return True
            logger.exception("write loop failed to handle entry %s", entry_id)
            return False
        self._ack(entry_id)
        return True


def _is_retryable_write_error(exc):
    import psycopg

    return isinstance(exc, (psycopg.OperationalError, psycopg.InterfaceError, redis.RedisError))


def handle_read_request(redis, conn, request, *, embed, prefix=PREFIX):
    from . import store

    cid = request["cid"]
    reply = request["reply"]
    if reply != reply_key(cid, prefix=prefix):
        return

    try:
        hits = store.retrieve(conn, request["query"], k=int(request.get("k", 8)), embed=embed)
        envelope = {"status": "ok", "hits": hits}
    except Exception as exc:
        envelope = {"status": "error", "error": str(exc)}

    redis.lpush(reply, json.dumps(envelope, default=str))
    redis.expire(reply, REPLY_TTL)


class ReadLoop:
    """Read pending recovery is cleanup-only: stale reads are acked without re-replying."""

    def __init__(self, redis, conn, *, embed, prefix=PREFIX, consumer="reader", block_ms=1000):
        self.redis = redis
        self.conn = conn
        self.embed = embed
        self.prefix = prefix
        self.consumer = consumer
        self.block_ms = block_ms
        self.stream = reads_stream(prefix)
        self.running = False
        ensure_group(self.redis, self.stream, GROUP)

    def step(self):
        rows = self.redis.xreadgroup(
            GROUP,
            self.consumer,
            {self.stream: ">"},
            count=1,
            block=self.block_ms,
        )
        entry = self._one_from_rows(rows)
        if entry is None:
            return None
        return self._handle_entry(*entry)

    def drain_pending(self):
        while True:
            try:
                rows = self.redis.xreadgroup(GROUP, self.consumer, {self.stream: "0"}, count=1)
                entry = self._one_from_rows(rows)
                if entry is None:
                    return
                entry_id, _ = entry
                self._ack(entry_id)
            except Exception:
                logger.exception("read loop pending cleanup failed")
                return

    def run(self):
        self.running = True
        self.drain_pending()
        while self.running:
            try:
                self.step()
            except Exception:
                logger.exception("read loop failed")

    def stop(self):
        self.running = False

    @staticmethod
    def _one_from_rows(rows):
        if not rows:
            return None
        _, entries = rows[0]
        if not entries:
            return None
        return entries[0]

    @staticmethod
    def _parse_request(fields):
        for key in ("cid", "reply", "query"):
            if key not in fields:
                raise ValueError(f"read request missing required {key}")
        return fields

    def _ack(self, entry_id):
        self.redis.xack(self.stream, GROUP, entry_id)

    def _handle_entry(self, entry_id, fields):
        try:
            request = self._parse_request(fields)
        except (TypeError, ValueError):
            logger.exception("dropping malformed read entry %s", entry_id)
            self._ack(entry_id)
            return None

        try:
            handle_read_request(self.redis, self.conn, request, embed=self.embed, prefix=self.prefix)
        except Exception:
            logger.exception("read loop failed to handle entry %s", entry_id)
            return None
        self._ack(entry_id)
        return request


class MemoryConsumer:
    def __init__(self, redis, conn_factory, *, embed, prefix=PREFIX):
        self.write_loop = WriteLoop(redis, conn_factory(), embed=embed, prefix=prefix, consumer="writer")
        self.read_loop = ReadLoop(redis, conn_factory(), embed=embed, prefix=prefix, consumer="reader")
        self.threads = []

    def start(self):
        if self.threads:
            return
        self.threads = [
            threading.Thread(target=self.write_loop.run, daemon=True),
            threading.Thread(target=self.read_loop.run, daemon=True),
        ]
        for thread in self.threads:
            thread.start()

    def stop(self):
        self.write_loop.stop()
        self.read_loop.stop()
        for thread in self.threads:
            thread.join(timeout=2.0)


def memory_query(redis, query_text, k=8, *, timeout_s, prefix=PREFIX):
    cid = uuid.uuid4().hex
    reply = reply_key(cid, prefix=prefix)
    redis.xadd(
        reads_stream(prefix),
        {"cid": cid, "reply": reply, "query": query_text, "k": str(k)},
        maxlen=MAXLEN,
        approximate=True,
    )

    timeout = max(1, math.ceil(timeout_s))
    popped = redis.blpop(reply, timeout=timeout)
    if popped is None:
        return None

    _, raw = popped
    envelope = json.loads(raw)
    if envelope.get("status") != "ok":
        return None
    return envelope.get("hits")

